module.exports = {
  "styleCss": "@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;600;800;900&display=swap');\n\n:root {\n  --primary-color: #0077b6;\n  --secondary-color: #00b4d8;\n  --accent-color: #fca311;\n  --dark-bg: #0b0c10;\n  --dark-surface: #1f2833;\n  --text-light: #ffffff;\n  --text-muted: #c5c6c7;\n  --glass-bg: rgba(31, 40, 51, 0.7);\n  --glass-border: rgba(255, 255, 255, 0.1);\n  --success: #2ecc71;\n  --transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: 'Cairo', sans-serif;\n  background-color: var(--dark-bg);\n  color: var(--text-light);\n  line-height: 1.6;\n  overflow-x: hidden;\n}\n\n/* Animations */\n@keyframes fadeInData {\n  0% { opacity: 0; transform: translateY(30px); }\n  100% { opacity: 1; transform: translateY(0); }\n}\n\n@keyframes float {\n  0% { transform: translateY(0px); }\n  50% { transform: translateY(-15px); }\n  100% { transform: translateY(0px); }\n}\n\n@keyframes pulse-glow {\n  0% { box-shadow: 0 0 0 0 rgba(252, 163, 17, 0.6); }\n  70% { box-shadow: 0 0 0 15px rgba(252, 163, 17, 0); }\n  100% { box-shadow: 0 0 0 0 rgba(252, 163, 17, 0); }\n}\n\n.animate-on-scroll {\n  opacity: 0;\n  transform: translateY(40px);\n  transition: var(--transition);\n}\n\n.animate-on-scroll.visible {\n  opacity: 1;\n  transform: translateY(0);\n}\n\n/* Typography */\nh1, h2, h3, h4 {\n  font-weight: 800;\n  color: var(--text-light);\n  margin-bottom: 1rem;\n}\n\nh1 {\n  font-size: 3.5rem;\n  line-height: 1.2;\n}\n\nh2 {\n  font-size: 2.5rem;\n  text-align: center;\n  position: relative;\n  display: inline-block;\n  margin-bottom: 3rem;\n}\n\nh2::after {\n  content: '';\n  position: absolute;\n  bottom: -10px;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 60px;\n  height: 4px;\n  background: var(--accent-color);\n  border-radius: 2px;\n}\n\np {\n  color: var(--text-muted);\n  font-size: 1.1rem;\n}\n\na {\n  text-decoration: none;\n  color: var(--text-light);\n  transition: var(--transition);\n}\n\n/* Layout Classes */\n.container {\n  width: 100%;\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 0 20px;\n}\n\n.section {\n  padding: 100px 0;\n  position: relative;\n}\n\n/* Glassmorphism Utilities */\n.glass-panel {\n  background: var(--glass-bg);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n  border: 1px solid var(--glass-border);\n  border-radius: 16px;\n  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.3);\n}\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 14px 32px;\n  border-radius: 50px;\n  font-weight: 600;\n  font-size: 1.1rem;\n  cursor: pointer;\n  transition: var(--transition);\n  border: none;\n  outline: none;\n  position: relative;\n  overflow: hidden;\n  z-index: 1;\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));\n  color: #fff;\n  box-shadow: 0 4px 15px rgba(0, 119, 182, 0.4);\n}\n\n.btn-primary:hover {\n  transform: translateY(-3px) scale(1.02);\n  box-shadow: 0 10px 25px rgba(0, 119, 182, 0.6);\n}\n\n.btn-accent {\n  background: var(--accent-color);\n  color: var(--dark-bg);\n  box-shadow: 0 4px 15px rgba(252, 163, 17, 0.4);\n}\n\n.btn-accent:hover {\n  transform: translateY(-3px) scale(1.02);\n  box-shadow: 0 10px 25px rgba(252, 163, 17, 0.6);\n  animation: pulse-glow 1.5s infinite;\n}\n\n.btn-outline {\n  background: transparent;\n  border: 2px solid var(--secondary-color);\n  color: var(--secondary-color);\n}\n\n.btn-outline:hover {\n  background: var(--secondary-color);\n  color: #fff;\n  transform: translateY(-3px);\n}\n\n/* Header & Navigation */\nheader {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100%;\n  z-index: 1000;\n  padding: 20px 0;\n  transition: var(--transition);\n}\n\nheader.scrolled {\n  background: var(--glass-bg);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  padding: 10px 0;\n  border-bottom: 1px solid var(--glass-border);\n}\n\n.nav-container {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.logo {\n  font-size: 1.8rem;\n  font-weight: 900;\n  color: var(--accent-color);\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.logo span {\n  color: var(--text-light);\n}\n\n.nav-links {\n  display: flex;\n  list-style: none;\n  gap: 30px;\n}\n\n.nav-links a {\n  font-weight: 600;\n  position: relative;\n  padding: 5px 0;\n}\n\n.nav-links a::after {\n  content: '';\n  position: absolute;\n  bottom: 0;\n  right: 0;\n  width: 0;\n  height: 2px;\n  background: var(--accent-color);\n  transition: var(--transition);\n}\n\n.nav-links a:hover::after,\n.nav-links a.active::after {\n  width: 100%;\n  left: 0;\n  right: auto;\n}\n\n.mobile-toggle {\n  display: none;\n  font-size: 1.5rem;\n  cursor: pointer;\n  color: var(--text-light);\n}\n\n/* Hero Section */\n.hero {\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  position: relative;\n  overflow: hidden;\n  padding-top: 80px;\n}\n\n.hero-bg {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  z-index: -2;\n  transform: scale(1.05);\n}\n\n.hero-overlay {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(to right, rgba(11, 12, 16, 0.95) 0%, rgba(11, 12, 16, 0.5) 100%);\n  z-index: -1;\n}\n\n.hero-content {\n  max-width: 600px;\n  animation: fadeInData 1.5s ease-out;\n}\n\n.hero-tag {\n  display: inline-block;\n  padding: 6px 16px;\n  background: rgba(0, 180, 216, 0.2);\n  color: var(--secondary-color);\n  border-radius: 50px;\n  border: 1px solid var(--secondary-color);\n  font-weight: 600;\n  margin-bottom: 20px;\n  letter-spacing: 1px;\n}\n\n.hero-content h1 span {\n  background: linear-gradient(135deg, var(--accent-color), #ffcf54);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.hero-btns {\n  display: flex;\n  gap: 15px;\n  margin-top: 30px;\n}\n\n/* Features/Stats Section */\n.stats {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 30px;\n  margin-top: -50px;\n  position: relative;\n  z-index: 10;\n}\n\n.stat-card {\n  text-align: center;\n  padding: 30px;\n  transition: var(--transition);\n}\n\n.stat-card:hover {\n  transform: translateY(-10px);\n  border-color: var(--secondary-color);\n}\n\n.stat-icon {\n  font-size: 2.5rem;\n  color: var(--secondary-color);\n  margin-bottom: 15px;\n}\n\n.stat-number {\n  font-size: 2.5rem;\n  font-weight: 900;\n  color: var(--text-light);\n  margin-bottom: 5px;\n}\n\n.stat-label {\n  color: var(--text-muted);\n  font-weight: 600;\n}\n\n/* Cards Grid */\n.cards-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n  gap: 30px;\n  margin-top: 50px;\n}\n\n.college-card {\n  border-radius: 16px;\n  overflow: hidden;\n  background: var(--dark-surface);\n  transition: var(--transition);\n  border: 1px solid transparent;\n  position: relative;\n}\n\n.college-card:hover {\n  transform: translateY(-10px);\n  border-color: var(--secondary-color);\n  box-shadow: 0 15px 30px rgba(0, 119, 182, 0.2);\n}\n\n.card-img-wrapper {\n  height: 200px;\n  overflow: hidden;\n  position: relative;\n}\n\n.card-img-wrapper img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  transition: transform 0.6s ease;\n}\n\n.college-card:hover .card-img-wrapper img {\n  transform: scale(1.1);\n}\n\n.card-overlay {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(to top, var(--dark-surface), transparent);\n}\n\n.card-content {\n  padding: 25px;\n}\n\n.card-title {\n  font-size: 1.4rem;\n  color: var(--secondary-color);\n  margin-bottom: 10px;\n}\n\n.card-desc {\n  font-size: 0.95rem;\n  margin-bottom: 20px;\n}\n\n.card-action {\n  display: flex;\n  align-items: center;\n  color: var(--accent-color);\n  font-weight: 600;\n  gap: 8px;\n}\n\n.card-action i {\n  transition: transform 0.3s ease;\n}\n\n.college-card:hover .card-action i {\n  transform: translateX(-5px);\n}\n\n/* Forms Subsystem */\n.form-wrapper {\n  max-width: 800px;\n  margin: 0 auto;\n  padding: 40px;\n  position: relative;\n}\n\n.form-wrapper::before {\n  content: '';\n  position: absolute;\n  top: -50px;\n  right: -50px;\n  width: 150px;\n  height: 150px;\n  background: var(--secondary-color);\n  border-radius: 50%;\n  filter: blur(80px);\n  z-index: -1;\n  opacity: 0.6;\n}\n.form-wrapper::after {\n  content: '';\n  position: absolute;\n  bottom: -50px;\n  left: -50px;\n  width: 200px;\n  height: 200px;\n  background: var(--primary-color);\n  border-radius: 50%;\n  filter: blur(100px);\n  z-index: -1;\n  opacity: 0.6;\n}\n\n.form-group {\n  margin-bottom: 20px;\n}\n\n.form-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 20px;\n}\n\n.form-label {\n  display: block;\n  margin-bottom: 8px;\n  font-weight: 600;\n  color: var(--text-light);\n}\n\n.form-control {\n  width: 100%;\n  padding: 15px 20px;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid var(--glass-border);\n  border-radius: 8px;\n  color: var(--text-light);\n  font-family: inherit;\n  font-size: 1rem;\n  transition: var(--transition);\n}\n\n.form-control:focus {\n  outline: none;\n  border-color: var(--secondary-color);\n  background: rgba(255, 255, 255, 0.1);\n  box-shadow: 0 0 0 3px rgba(0, 180, 216, 0.2);\n}\n\ntextarea.form-control {\n  min-height: 120px;\n  resize: vertical;\n}\n\nselect.form-control {\n  appearance: none;\n  background-image: url(\"data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23ffffff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e\");\n  background-repeat: no-repeat;\n  background-position: left 15px center;\n  background-size: 15px;\n}\n\nselect.form-control option {\n  background: var(--dark-surface);\n  color: var(--text-light);\n}\n\n/* Footer Element */\nfooter {\n  background: var(--dark-surface);\n  padding: 60px 0 20px;\n  margin-top: 50px;\n  border-top: 1px solid var(--glass-border);\n}\n\n.footer-grid {\n  display: grid;\n  grid-template-columns: 2fr 1fr 1fr;\n  gap: 40px;\n  margin-bottom: 40px;\n}\n\n.footer-about p {\n  margin-top: 20px;\n  max-width: 400px;\n}\n\n.social-links {\n  display: flex;\n  gap: 15px;\n  margin-top: 20px;\n}\n\n.social-links a {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 40px;\n  height: 40px;\n  border-radius: 50%;\n  background: rgba(255, 255, 255, 0.05);\n  font-size: 1.2rem;\n  transition: var(--transition);\n}\n\n.social-links a:hover {\n  background: var(--secondary-color);\n  transform: translateY(-5px);\n}\n\n.footer-links h4 {\n  font-size: 1.2rem;\n  margin-bottom: 20px;\n  color: var(--accent-color);\n}\n\n.footer-links ul {\n  list-style: none;\n}\n\n.footer-links li {\n  margin-bottom: 10px;\n}\n\n.footer-links a {\n  display: inline-block;\n  color: var(--text-muted);\n}\n\n.footer-links a:hover {\n  color: var(--secondary-color);\n  transform: translateX(-5px);\n}\n\n.copyright {\n  text-align: center;\n  padding-top: 20px;\n  border-top: 1px solid rgba(255, 255, 255, 0.05);\n  color: var(--text-muted);\n  font-size: 0.9rem;\n}\n\n/* Success Modal */\n.modal-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: rgba(0, 0, 0, 0.8);\n  backdrop-filter: blur(5px);\n  z-index: 2000;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  opacity: 0;\n  pointer-events: none;\n  transition: var(--transition);\n}\n\n.modal-overlay.active {\n  opacity: 1;\n  pointer-events: all;\n}\n\n.modal-content {\n  background: var(--dark-surface);\n  padding: 40px;\n  border-radius: 16px;\n  text-align: center;\n  max-width: 400px;\n  transform: scale(0.8);\n  transition: var(--transition);\n  border: 1px solid var(--glass-border);\n}\n\n.modal-overlay.active .modal-content {\n  transform: scale(1);\n}\n\n.success-icon {\n  width: 80px;\n  height: 80px;\n  border-radius: 50%;\n  background: rgba(46, 204, 113, 0.2);\n  color: var(--success);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 2.5rem;\n  margin: 0 auto 20px;\n}\n\n/* Simple Responsive */\n@media (max-width: 768px) {\n  .nav-links {\n    position: fixed;\n    top: 80px;\n    right: -100%;\n    width: 250px;\n    height: 100vh;\n    background: var(--glass-bg);\n    backdrop-filter: blur(16px);\n    -webkit-backdrop-filter: blur(16px);\n    flex-direction: column;\n    padding: 40px 20px;\n    transition: var(--transition);\n    border-left: 1px solid var(--glass-border);\n  }\n  \n  .nav-links.active {\n    right: 0;\n  }\n  \n  .mobile-toggle {\n    display: block;\n  }\n\n  h1 { font-size: 2.5rem; }\n  h2 { font-size: 2rem; }\n  \n  .form-row { grid-template-columns: 1fr; }\n  .footer-grid { grid-template-columns: 1fr; gap: 30px; text-align: center; }\n  \n  .footer-links a:hover { transform: translateY(-3px); }\n  .social-links { justify-content: center; }\n}\n",
  "adminCss": "/* --------------------------------------------------\n   ADMIN DASHBOARD CUSTOM STYLES\n   -------------------------------------------------- */\n\n.admin-body {\n    background: var(--dark-bg);\n    color: var(--text-light);\n    font-family: 'Cairo', system-ui, sans-serif;\n    margin: 0;\n    padding: 0;\n    min-height: 100vh;\n}\n\n/* Login Screen Overlay */\n.admin-login-overlay {\n    position: fixed;\n    top: 0; left: 0; right: 0; bottom: 0;\n    background: linear-gradient(135deg, rgba(11, 12, 16, 0.95), rgba(31, 40, 51, 0.98)), url('../assets/images/hero.webp') center/cover fixed;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 9999;\n    padding: 20px;\n}\n\n.login-card {\n    width: 100%;\n    max-width: 440px;\n    padding: 35px 30px;\n    border-radius: 24px;\n    border: 1px solid var(--glass-border);\n    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.6);\n}\n\n.login-header {\n    text-align: center;\n    margin-bottom: 30px;\n}\n\n.login-logo-icon {\n    width: 65px;\n    height: 65px;\n    border-radius: 50%;\n    background: var(--accent-color);\n    color: var(--dark-bg);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 2rem;\n    margin: 0 auto 15px;\n    box-shadow: 0 10px 25px rgba(252, 163, 17, 0.4);\n}\n\n.login-header h2 {\n    font-size: 1.6rem;\n    color: #fff;\n    margin-bottom: 5px;\n}\n\n.login-header p {\n    color: var(--text-muted);\n    font-size: 0.9rem;\n}\n\n.login-footer-hint {\n    margin-top: 25px;\n    padding-top: 15px;\n    border-top: 1px solid var(--glass-border);\n    text-align: center;\n    font-size: 0.8rem;\n    color: var(--text-muted);\n}\n\n.alert-box.error {\n    background: rgba(231, 76, 60, 0.15);\n    border: 1px solid rgba(231, 76, 60, 0.4);\n    color: #ff6b6b;\n    padding: 10px 14px;\n    border-radius: 10px;\n    font-size: 0.88rem;\n}\n\n/* Dashboard Layout */\n.admin-layout {\n    display: flex;\n    min-height: 100vh;\n}\n\n/* Sidebar */\n.admin-sidebar {\n    width: 270px;\n    background: rgba(11, 12, 16, 0.95);\n    border-left: 1px solid var(--glass-border);\n    display: flex;\n    flex-direction: column;\n    position: fixed;\n    top: 0; bottom: 0; right: 0;\n    z-index: 100;\n    backdrop-filter: blur(20px);\n}\n\n.sidebar-header {\n    padding: 25px 20px;\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    border-bottom: 1px solid var(--glass-border);\n}\n\n.sidebar-logo-icon {\n    font-size: 2rem;\n    color: var(--accent-color);\n}\n\n.sidebar-brand h3 {\n    font-size: 1.2rem;\n    color: #fff;\n    margin: 0;\n}\n\n.sidebar-brand span {\n    font-size: 0.75rem;\n    color: var(--secondary-color);\n    font-weight: 700;\n}\n\n.sidebar-menu {\n    padding: 20px 12px;\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    flex: 1;\n    overflow-y: auto;\n}\n\n.menu-item {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 12px 16px;\n    color: var(--text-light);\n    text-decoration: none;\n    border-radius: 12px;\n    font-size: 0.95rem;\n    font-weight: 600;\n    transition: var(--transition);\n}\n\n.menu-item i {\n    font-size: 1.1rem;\n    width: 20px;\n    text-align: center;\n    color: var(--text-muted);\n}\n\n.menu-item:hover, .menu-item.active {\n    background: var(--secondary-color);\n    color: #fff;\n}\n\n.menu-item:hover i, .menu-item.active i {\n    color: #fff;\n}\n\n.badge-count {\n    margin-right: auto;\n    background: var(--accent-color);\n    color: var(--dark-bg);\n    padding: 2px 8px;\n    border-radius: 50px;\n    font-size: 0.75rem;\n    font-weight: 800;\n}\n\n.sidebar-footer {\n    padding: 15px 20px;\n    border-top: 1px solid var(--glass-border);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n}\n\n.user-info {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.user-info i {\n    font-size: 2rem;\n    color: var(--accent-color);\n}\n\n.user-info strong {\n    display: block;\n    font-size: 0.9rem;\n}\n\n.user-info small {\n    font-size: 0.75rem;\n    color: var(--text-muted);\n}\n\n.logout-btn {\n    background: rgba(231, 76, 60, 0.2);\n    color: #ff6b6b;\n    border: 1px solid rgba(231, 76, 60, 0.4);\n    width: 38px;\n    height: 38px;\n    border-radius: 10px;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: var(--transition);\n}\n\n.logout-btn:hover {\n    background: #e74c3c;\n    color: #fff;\n}\n\n/* Main Content */\n.admin-main {\n    margin-right: 270px;\n    flex: 1;\n    padding: 30px;\n    max-width: calc(100vw - 270px);\n}\n\n.admin-topbar {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 15px 25px;\n    border-radius: 16px;\n    margin-bottom: 30px;\n}\n\n.topbar-title h2 {\n    font-size: 1.4rem;\n    margin: 0;\n    color: var(--accent-color);\n}\n\n.flex-gap {\n    display: flex;\n    gap: 10px;\n    align-items: center;\n}\n\n/* Stats Cards */\n.stats-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n    gap: 20px;\n}\n\n.admin-stat-card {\n    padding: 20px;\n    border-radius: 16px;\n    display: flex;\n    align-items: center;\n    gap: 18px;\n    transition: var(--transition);\n}\n\n.admin-stat-card:hover {\n    transform: translateY(-4px);\n}\n\n.stat-icon-wrapper {\n    width: 55px;\n    height: 55px;\n    border-radius: 14px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 1.6rem;\n}\n\n.stat-icon-wrapper.accent { background: rgba(252, 163, 17, 0.15); color: var(--accent-color); }\n.stat-icon-wrapper.warning { background: rgba(241, 196, 15, 0.15); color: #f1c40f; }\n.stat-icon-wrapper.success { background: rgba(46, 204, 113, 0.15); color: #2ecc71; }\n.stat-icon-wrapper.info { background: rgba(0, 180, 216, 0.15); color: var(--secondary-color); }\n\n.stat-title {\n    font-size: 0.85rem;\n    color: var(--text-muted);\n}\n\n.stat-value {\n    font-size: 1.8rem;\n    font-weight: 800;\n    color: #fff;\n    margin: 2px 0;\n}\n\n.stat-sub {\n    font-size: 0.75rem;\n    color: var(--text-light);\n    opacity: 0.7;\n}\n\n/* Section Cards & Tables */\n.section-card {\n    border-radius: 20px;\n    padding: 25px;\n}\n\n.card-header-flex {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    flex-wrap: wrap;\n    gap: 15px;\n}\n\n.search-box {\n    position: relative;\n    min-width: 250px;\n}\n\n.search-box.full {\n    width: 100%;\n}\n\n.search-box i {\n    position: absolute;\n    right: 14px;\n    top: 50%;\n    transform: translateY(-50%);\n    color: var(--text-muted);\n}\n\n.search-box input {\n    width: 100%;\n    padding: 10px 40px 10px 15px;\n    border-radius: 50px;\n    border: 1px solid var(--glass-border);\n    background: rgba(255, 255, 255, 0.05);\n    color: #fff;\n    font-size: 0.9rem;\n    outline: none;\n}\n\n.search-box input:focus {\n    border-color: var(--accent-color);\n}\n\n/* Quick Department Cards Grid */\n.quick-depts-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));\n    gap: 20px;\n    margin-top: 25px;\n}\n\n.dept-ctrl-card {\n    background: var(--dark-surface);\n    border: 1px solid var(--glass-border);\n    border-radius: 16px;\n    padding: 20px;\n    transition: var(--transition);\n}\n\n.dept-ctrl-card:hover {\n    border-color: rgba(252, 163, 17, 0.4);\n    box-shadow: 0 10px 25px rgba(0,0,0,0.4);\n}\n\n.dept-card-top {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 15px;\n}\n\n.dept-name-badge {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.dept-name-badge i {\n    font-size: 1.4rem;\n    color: var(--accent-color);\n}\n\n.dept-name-badge h4 {\n    margin: 0;\n    font-size: 1.1rem;\n    color: #fff;\n}\n\n.dept-category-tag {\n    font-size: 0.75rem;\n    padding: 3px 10px;\n    border-radius: 50px;\n    background: rgba(255, 255, 255, 0.08);\n    color: var(--text-muted);\n}\n\n.grade-control-row {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    background: rgba(0, 0, 0, 0.2);\n    padding: 12px;\n    border-radius: 12px;\n    margin-bottom: 10px;\n}\n\n.grade-label {\n    font-size: 0.85rem;\n    font-weight: 700;\n    color: var(--text-light);\n}\n\n.grade-adjusters {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n}\n\n.grade-btn {\n    width: 32px;\n    height: 32px;\n    border-radius: 8px;\n    border: 1px solid var(--glass-border);\n    background: rgba(255, 255, 255, 0.08);\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.9rem;\n    cursor: pointer;\n    transition: var(--transition);\n}\n\n.grade-btn:hover {\n    background: var(--secondary-color);\n    border-color: var(--secondary-color);\n}\n\n.grade-btn.sub:hover {\n    background: #e74c3c;\n    border-color: #e74c3c;\n}\n\n.grade-btn.add:hover {\n    background: #2ecc71;\n    border-color: #2ecc71;\n}\n\n.grade-input {\n    width: 60px;\n    text-align: center;\n    padding: 5px;\n    border-radius: 8px;\n    border: 1px solid var(--glass-border);\n    background: rgba(255, 255, 255, 0.1);\n    color: var(--accent-color);\n    font-weight: 800;\n    font-size: 1rem;\n}\n\n/* Tables */\n.table-responsive {\n    overflow-x: auto;\n}\n\n.admin-table {\n    width: 100%;\n    border-collapse: collapse;\n    margin-top: 15px;\n    text-align: right;\n}\n\n.admin-table th {\n    background: rgba(255, 255, 255, 0.04);\n    padding: 14px 16px;\n    font-size: 0.85rem;\n    color: var(--text-muted);\n    border-bottom: 2px solid var(--glass-border);\n}\n\n.admin-table td {\n    padding: 14px 16px;\n    border-bottom: 1px solid var(--glass-border);\n    font-size: 0.9rem;\n    color: var(--text-light);\n}\n\n.admin-table tr:hover {\n    background: rgba(255, 255, 255, 0.02);\n}\n\n/* Status Badges */\n.status-pill {\n    padding: 4px 12px;\n    border-radius: 50px;\n    font-size: 0.8rem;\n    font-weight: 700;\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n}\n\n.status-pill.pending { background: rgba(241, 196, 15, 0.2); color: #f1c40f; border: 1px solid rgba(241, 196, 15, 0.4); }\n.status-pill.accepted { background: rgba(46, 204, 113, 0.2); color: #2ecc71; border: 1px solid rgba(46, 204, 113, 0.4); }\n.status-pill.rejected { background: rgba(231, 76, 60, 0.2); color: #e74c3c; border: 1px solid rgba(231, 76, 60, 0.4); }\n\n/* Filter Tabs */\n.filter-tabs-wrapper {\n    display: flex;\n    gap: 8px;\n}\n\n.filter-tab {\n    padding: 6px 16px;\n    border-radius: 50px;\n    border: 1px solid var(--glass-border);\n    background: transparent;\n    color: var(--text-muted);\n    cursor: pointer;\n    font-size: 0.85rem;\n    transition: var(--transition);\n}\n\n.filter-tab.active, .filter-tab:hover {\n    background: var(--secondary-color);\n    color: #fff;\n    border-color: var(--secondary-color);\n}\n\n/* Modals */\n.admin-modal-overlay {\n    position: fixed;\n    top: 0; left: 0; right: 0; bottom: 0;\n    background: rgba(0, 0, 0, 0.75);\n    backdrop-filter: blur(10px);\n    z-index: 9000;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n}\n\n.admin-modal-card {\n    width: 100%;\n    max-width: 620px;\n    padding: 30px;\n    border-radius: 20px;\n    max-height: 90vh;\n    overflow-y: auto;\n}\n\n.modal-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 20px;\n    border-bottom: 1px solid var(--glass-border);\n    padding-bottom: 12px;\n}\n\n.modal-header h3 {\n    margin: 0;\n    color: var(--accent-color);\n}\n\n.modal-close-btn {\n    background: transparent;\n    border: none;\n    color: var(--text-muted);\n    font-size: 1.8rem;\n    cursor: pointer;\n}\n\n.modal-close-btn:hover { color: #fff; }\n\n.modal-footer {\n    display: flex;\n    justify-content: flex-end;\n    gap: 10px;\n}\n\n.req { color: #e74c3c; margin-right: 4px; }\n\n/* Responsive */\n@media (max-width: 900px) {\n    .admin-sidebar { width: 80px; }\n    .sidebar-brand, .sidebar-menu span, .user-info div { display: none; }\n    .admin-main { margin-right: 80px; max-width: calc(100vw - 80px); padding: 15px; }\n}\n",
  "mainJs": "document.addEventListener('DOMContentLoaded', () => {\n\n  // 1. Mobile Menu Toggle\n  const mobileToggle = document.querySelector('.mobile-toggle');\n  const navLinks = document.querySelector('.nav-links');\n\n  if (mobileToggle && navLinks) {\n    mobileToggle.addEventListener('click', () => {\n      navLinks.classList.toggle('active');\n      const icon = mobileToggle.querySelector('i');\n      if (icon) {\n        if (navLinks.classList.contains('active')) {\n          icon.classList.remove('fa-bars');\n          icon.classList.add('fa-times');\n        } else {\n          icon.classList.remove('fa-times');\n          icon.classList.add('fa-bars');\n        }\n      }\n    });\n  }\n\n  // 2. Scroll Effect for Header\n  const header = document.querySelector('header');\n  if (header) {\n    window.addEventListener('scroll', () => {\n      if (window.scrollY > 50) {\n        header.classList.add('scrolled');\n      } else {\n        header.classList.remove('scrolled');\n      }\n    });\n  }\n\n  // 3. Scroll Reveal Animations (Intersection Observer)\n  const animateElements = document.querySelectorAll('.animate-on-scroll');\n  \n  const observerOptions = {\n    root: null,\n    rootMargin: '0px',\n    threshold: 0.05\n  };\n\n  const observer = new IntersectionObserver((entries, observer) => {\n    entries.forEach(entry => {\n      if (entry.isIntersecting) {\n        entry.target.classList.add('visible');\n        observer.unobserve(entry.target);\n      }\n    });\n  }, observerOptions);\n\n  animateElements.forEach(el => observer.observe(el));\n\n});\n",
  "langJs": "const translations = {\n  ar: {\n    // Page Title\n    'title-index':'جامعة المعارف | بوابة المستقبل',\n    'title-admission':'الاستمارة الإلكترونية | جامعة المعارف',\n    'title-colleges':'الكليات والأقسام | جامعة المعارف',\n    'title-tuition':'أقساط الدراسة | جامعة المعارف',\n\n    // Nav & Logo\n    'nav-home':'الرئيسية','nav-about':'عن الجامعة','nav-colleges':'الكليات والأقسام','nav-tuition':'أقساط الدراسة','nav-register':'سجل الآن','nav-news':'الأخبار والنشاطات',\n    'logo-main':'جامعة','logo-span':'المعارف',\n    // Hero\n    'hero-tag':'بوابة التميز والإبداع','hero-h1-pre':'ابنِ مستقبلك في ','hero-h1-span':'جامعة المعارف',\n    'hero-p':'نوفر لك بيئة تعليمية حديثة، ومختبرات متطورة، وكوادر تدريسية متميزة لتكون قائد الطليعة في مجالك الأكاديمي والمهني.',\n    'hero-btn1':'استكشف الكليات','hero-btn2':'التسجيل الإلكتروني',\n    // Stats\n    'stat1-label':'أقسام علمية','stat2-label':'مختبرات متطورة','stat3-label':'طالب ومتميز','stat4-label':'اعتماد أكاديمي',\n    // About\n    'about-h2':'الرؤية والرسالة',\n    'about-p1':'نسعى في جامعة المعارف لأن نكون في مصاف الجامعات المتقدمة محلياً وعالمياً من خلال تقديم برامج تعليمية عالية الجودة تتوافق مع معايير الجودة العالمية وتلبي احتياجات سوق العمل.',\n    'about-p2':'مهمتنا هي بناء جيل معرفي قادر على الابتكار والابداع، مزود بالمهارات التقنية والمعرفية التي تمكنه من المساهمة الفعالة في بناء المجتمع وتطوير مخرجات البحث العلمي في البلاد.',\n    'about-li1':'استخدام أحدث التقنيات التعليمية.','about-li2':'توأمة علمية مع أرقى الجامعات العالمية.','about-li3':'بيئة جامعية متكاملة ومحفزة.',\n    // Colleges Overview (Home)\n    'colleges-h2':'كلياتنا الرائدة','colleges-p':'تضم جامعة المعارف مجموعة من الكليات العلمية والإنسانية الرائدة التي تتيح للطلاب مجموعة واسعة من الخيارات.',\n    'card1-title':'المجموعة الطبية والصحية','card1-desc':'تضم كليات (الصيدلة، طب الأسنان، التقنيات الطبية) توفر أحدث المختبرات للجانب العملي.',\n    'card2-title':'هندسة وتقنيات الحاسوب','card2-desc':'تشمل أقسام الهندسة المدنية، الميكاترونكس وهندسة أنظمة الحاسبات الحديثة والروبوتكس.',\n    'card3-title':'الكليات الإنسانية والإدارية','card3-desc':'تخرج قادة المستقبل من قضاة، ومحامين، ومدراء شركات عبر كليتي القانون والإدارة والاقتصاد.',\n    'card4-title':'التربية البدنية وعلوم الرياضة','card4-desc':'نعد أجيالاً من الرياضيين والمدربين المحترفين وفق أحدث المناهج العلمية والتدريبية العالمية.',\n    'card-action':'التفاصيل','cards-btn':'استعرض جميع الكليات والأقسام',\n    // Admission Form\n    'page-admission-title':'استمارة التسجيل المبدئي','page-admission-p':'يرجى ملء البيانات بدقة ليتسنى لفريق القبول والتسجيل التواصل معك',\n    'lbl-name':'الاسم الرباعي','ph-name':'أدخل اسمك الرباعي هنا',\n    'lbl-phone':'رقم الهاتف (واتساب)','ph-phone':'07X XXXX XXXX',\n    'lbl-email':'البريد الإلكتروني','ph-email':'example@email.com',\n    'lbl-city':'المحافظة / السكن',\n    'lbl-branch':'الفرع الدراسي',\n    'lbl-grade':'المعدل الدراسي','ph-grade':'مثال: 85.5',\n    'lbl-college':'الكلية المراد التسجيل فيها',\n    'lbl-studytype':'نوع الدراسة المفضل',\n    'lbl-notes':'ملاحظات إضافية (اختياري)','ph-notes':'اكتب أي استفسار أو ملاحظة هنا...',\n    'btn-submit':'حفظ الاستمارة في قاعدة البيانات والإرسال','btn-sending':'جاري الإرسال...','btn-success':'تم الإرسال بنجاح!',\n    'form-sec2':'البيانات الأكاديمية ومعدل القبول',\n    // Form Options & Misc\n    'opt-select':'اختر...',\n    'city-bgd':'بغداد','city-anb':'الأنبار','city-erbil':'أربيل','city-basra':'البصرة','city-other':'محافظة أخرى',\n    'branch-bio':'العلمي - الأحيائي','branch-app':'العلمي - التطبيقي','branch-lit':'الأدبي','branch-voc':'المهني / الصناعي',\n    'study-morn':'صباحي','study-eve':'مسائي',\n    // Success Modal\n    'modal-h2':'تم التسجيل بنجاح!','modal-p':'أهلاً بك في عائلة جامعة المعارف. قمنا باستلام بياناتك وحفظها في قاعدة البيانات، وسيتم التواصل معك قريباً لاستكمال الإجراءات.','modal-btn':'العودة للرئيسية',\n    // Footer\n    'footer-about':'صرح تعليمي يهدف للارتقاء بالمستوى الأكاديمي والبحثي لتخريج كفاءات تساهم في بناء المجتمع وفقا لمعايير الجودة الشاملة.',\n    'footer-links-h':'روابط سريعة','footer-contact':'تواصل معنا','footer-addr':'العراق، الأنبار، الرمادي',\n    'footer-copy':'© 2026 جميع الحقوق محفوظة لجامعة المعارف الأهلية',\n    'footer-dev':'تم التصميم للتطوير المتقدم',\n    // Tuition\n    'page-tuition-h1':'أقساط الدراسة والحد الأدنى للقبول','page-tuition-p':'جدول شامل بأقساط الدراسة السنوية لجميع كليات وأقسام جامعة المعارف الأهلية ومعدلات القبول المقرة',\n    // Colleges Page\n    'page-colleges-h1':'الكليات والأقسام العلمية','page-colleges-p':'تعرف على كليات وأقسام جامعة المعارف الأهلية، واختر التخصص الذي يناسب مسارك وطموحك.',\n    'filter-all':'الكل','filter-medical':'الطبية والصحية','filter-eng':'الهندسة والعلوم','filter-hum':'العلوم الإنسانية'\n  },\n  en: {\n    // Page Title\n    'title-index':'Al-Maarif University | Future Gateway',\n    'title-admission':'Online Registration | Al-Maarif University',\n    'title-colleges':'Colleges & Departments | Al-Maarif University',\n    'title-tuition':'Tuition Fees | Al-Maarif University',\n\n    // Nav & Logo\n    'nav-home':'Home','nav-about':'About','nav-colleges':'Colleges','nav-tuition':'Tuition','nav-register':'Register','nav-news':'News & Activities',\n    'logo-main':'Al-Maarif','logo-span':'University',\n    // Hero\n    'hero-tag':'Gateway to Excellence','hero-h1-pre':'Build Your Future at ','hero-h1-span':'Al-Maarif University',\n    'hero-p':'We provide a modern environment and advanced laboratories to make you a leader in your field.',\n    'hero-btn1':'Explore Colleges','hero-btn2':'Online Registration',\n    // Stats\n    'stat1-label':'Scientific Departments','stat2-label':'Advanced Labs','stat3-label':'Distinguished Students','stat4-label':'Academic Accreditation',\n    // About\n    'about-h2':'Vision & Mission',\n    'about-p1':'At Al-Maarif University, we strive to be among the leading universities locally and globally.',\n    'about-p2':'Our mission is to build a generation capable of innovation.',\n    'about-li1':'Using the latest educational technologies.','about-li2':'Scientific twinning with top global universities.','about-li3':'Integrated and motivating environment.',\n    // Colleges Overview (Home)\n    'colleges-h2':'Our Leading Colleges','colleges-p':'Al-Maarif University includes a group of leading scientific and humanistic colleges.',\n    'card1-title':'Medical & Health Group','card1-desc':'Includes Pharmacy, Dentistry, Medical Techniques with state-of-the-art labs.',\n    'card2-title':'Engineering & IT','card2-desc':'Includes Civil Engineering, Mechatronics, and modern Computer Systems Engineering.',\n    'card3-title':'Humanities & Administration','card3-desc':'Graduating future leaders through the colleges of Law and Administration.',\n    'card4-title':'Physical Education & Sports','card4-desc':'Preparing generations of professional athletes and coaches.',\n    'card-action':'Details','cards-btn':'View All Colleges & Departments',\n    // Admission Form\n    'page-admission-title':'Initial Registration Form','page-admission-p':'Please fill in your details accurately so our team can contact you',\n    'lbl-name':'Full Name','ph-name':'Enter your full name here',\n    'lbl-phone':'Phone (WhatsApp)','ph-phone':'07X XXXX XXXX',\n    'lbl-email':'Email Address','ph-email':'example@email.com',\n    'lbl-city':'City / Residence',\n    'lbl-branch':'Study Branch',\n    'lbl-grade':'Academic Grade','ph-grade':'Example: 85.5',\n    'lbl-college':'Desired College',\n    'lbl-studytype':'Preferred Study',\n    'lbl-notes':'Additional Notes','ph-notes':'Write your notes here...',\n    'btn-submit':'Save Application to Database & Send','btn-sending':'Sending...','btn-success':'Sent Successfully!',\n    'form-sec2':'Academic Information & Grade',\n    // Form Options & Misc\n    'opt-select':'Select...',\n    'city-bgd':'Baghdad','city-anb':'Anbar','city-erbil':'Erbil','city-basra':'Basra','city-other':'Other City',\n    'branch-bio':'Scientific - Biological','branch-app':'Scientific - Applied','branch-lit':'Literary','branch-voc':'Vocational',\n    'study-morn':'Morning','study-eve':'Evening',\n    // Success Modal\n    'modal-h2':'Registered Successfully!','modal-p':'Welcome to Al-Maarif University. Your data has been saved in the database.','modal-btn':'Back to Home',\n    // Footer\n    'footer-about':'An educational landmark aiming to elevate academic levels.',\n    'footer-links-h':'Quick Links','footer-contact':'Contact Us','footer-addr':'Iraq, Anbar, Ramadi',\n    'footer-copy':'© 2026 Al-Maarif Private University. All Rights Reserved',\n    'footer-dev':'Developed by Advanced Dev Team',\n    // Tuition\n    'page-tuition-h1':'Fees & Admission Scores','page-tuition-p':'Comprehensive annual tuition fee schedule and cutoffs for all colleges',\n    // Colleges Page\n    'page-colleges-h1':'Academic Colleges','page-colleges-p':'Discover our colleges and choose your future path.',\n    'filter-all':'All','filter-medical':'Medical','filter-eng':'Engineering','filter-hum':'Humanities'\n  }\n};\n\nfunction applyLang(lang) {\n  const t = translations[lang];\n  if (!t) return;\n  const isAr = lang === 'ar';\n  document.documentElement.lang = isAr ? 'ar' : 'en';\n  document.documentElement.dir  = isAr ? 'rtl' : 'ltr';\n\n  document.querySelectorAll('[data-i18n]').forEach(el => {\n    const key = el.getAttribute('data-i18n');\n    if (t[key]) el.textContent = t[key];\n  });\n\n  document.querySelectorAll('[data-i18n-ph]').forEach(el => {\n    const key = el.getAttribute('data-i18n-ph');\n    if (t[key]) el.placeholder = t[key];\n  });\n\n  const btn = document.getElementById('langToggleBtn');\n  if (btn) btn.textContent = isAr ? 'EN' : 'ع';\n\n  localStorage.setItem('lang', lang);\n}\n\nfunction toggleLang() {\n  const current = localStorage.getItem('lang') || 'ar';\n  applyLang(current === 'ar' ? 'en' : 'ar');\n}\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  const saved = localStorage.getItem('lang') || 'ar';\n  applyLang(saved);\n});\n",
  "adminJs": "// --------------------------------------------------\n// AL-MAARIF COLLEGE ADMIN DASHBOARD CLIENT CONTROLLER\n// --------------------------------------------------\n\nconst API_BASE = window.location.origin;\nlet currentUser = null;\nlet allDepartments = [];\nlet allStudents = [];\n\n// Initialize Dashboard\ndocument.addEventListener('DOMContentLoaded', () => {\n    checkAuthToken();\n    setupLoginForm();\n});\n\n// Check JWT Token\nfunction checkAuthToken() {\n    const token = localStorage.getItem('adminToken');\n    if (!token) {\n        showLoginScreen();\n        return;\n    }\n\n    fetch(`${API_BASE}/api/auth/me`, {\n        headers: { 'Authorization': `Bearer ${token}` }\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            currentUser = data.user;\n            showDashboardLayout();\n            loadDashboardData();\n        } else {\n            logoutAdmin();\n        }\n    })\n    .catch(() => showLoginScreen());\n}\n\n// Show/Hide Screens\nfunction showLoginScreen() {\n    document.getElementById('loginScreen').style.display = 'flex';\n    document.getElementById('adminLayout').style.display = 'none';\n}\n\nfunction showDashboardLayout() {\n    document.getElementById('loginScreen').style.display = 'none';\n    document.getElementById('adminLayout').style.display = 'flex';\n    if (currentUser) {\n        document.getElementById('adminUserName').textContent = currentUser.full_name || currentUser.username;\n    }\n}\n\n// Login Form Submit\nfunction setupLoginForm() {\n    const form = document.getElementById('loginForm');\n    if (!form) return;\n\n    form.addEventListener('submit', (e) => {\n        e.preventDefault();\n        const username = document.getElementById('loginUsername').value.trim();\n        const password = document.getElementById('loginPassword').value.trim();\n        const alertBox = document.getElementById('loginAlert');\n\n        alertBox.style.display = 'none';\n\n        fetch(`${API_BASE}/api/auth/login`, {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ username, password })\n        })\n        .then(res => res.json())\n        .then(data => {\n            if (data.success) {\n                localStorage.setItem('adminToken', data.token);\n                currentUser = data.user;\n                showDashboardLayout();\n                loadDashboardData();\n            } else {\n                alertBox.textContent = data.message || 'خطأ في المصادقة';\n                alertBox.style.display = 'block';\n            }\n        })\n        .catch(err => {\n            alertBox.textContent = 'حدث خطأ بالاتصال بالسيرفر';\n            alertBox.style.display = 'block';\n        });\n    });\n}\n\n// Logout\nfunction logoutAdmin() {\n    localStorage.removeItem('adminToken');\n    currentUser = null;\n    showLoginScreen();\n}\n\n// Load All Dashboard Data\nfunction loadDashboardData() {\n    fetchStats();\n    fetchDepartments();\n    fetchStudents('all');\n}\n\n// Get Stats\nfunction fetchStats() {\n    const token = localStorage.getItem('adminToken');\n    fetch(`${API_BASE}/api/stats`, {\n        headers: { 'Authorization': `Bearer ${token}` }\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            const s = data.data;\n            document.getElementById('statTotalStudents').textContent = s.totalStudents || 0;\n            document.getElementById('statPendingStudents').textContent = s.pendingCount || 0;\n            document.getElementById('statAcceptedStudents').textContent = s.acceptedCount || 0;\n            document.getElementById('statTotalDepts').textContent = s.totalDepartments || 0;\n            document.getElementById('sidebarPendingCount').textContent = s.pendingCount || 0;\n        }\n    })\n    .catch(err => console.error('Error fetching stats:', err));\n}\n\n// Get Departments\nfunction fetchDepartments() {\n    fetch(`${API_BASE}/api/departments`)\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            allDepartments = data.data;\n            renderQuickDepts(allDepartments);\n            renderDepartmentsTable(allDepartments);\n        }\n    })\n    .catch(err => console.error('Error fetching departments:', err));\n}\n\n// Render Quick Department Cards (with + / - grade controls)\nfunction renderQuickDepts(depts) {\n    const grid = document.getElementById('quickDeptsGrid');\n    if (!grid) return;\n    grid.innerHTML = '';\n\n    if (depts.length === 0) {\n        grid.innerHTML = '<div style=\"grid-column: 1/-1; text-align: center; color: var(--text-muted); padding: 30px;\">لا توجد أقسام مسجلة حالياً</div>';\n        return;\n    }\n\n    depts.forEach(d => {\n        const card = document.createElement('div');\n        card.className = 'dept-ctrl-card';\n        card.innerHTML = `\n            <div class=\"dept-card-top\">\n                <div class=\"dept-name-badge\">\n                    <i class=\"fas ${d.icon_class || 'fa-graduation-cap'}\"></i>\n                    <div>\n                        <h4>${d.dept_name_ar}</h4>\n                        <small style=\"color: var(--text-muted);\">${d.college_name_ar}</small>\n                    </div>\n                </div>\n                <span class=\"dept-category-tag\">${getCatLabel(d.category)}</span>\n            </div>\n\n            <!-- Morning Avg Control -->\n            <div class=\"grade-control-row\">\n                <span class=\"grade-label\">صباحي:</span>\n                <div class=\"grade-adjusters\">\n                    <button class=\"grade-btn sub\" onclick=\"changeGrade(${d.id}, 'morning', -1.0)\">-1</button>\n                    <button class=\"grade-btn sub\" onclick=\"changeGrade(${d.id}, 'morning', -0.5)\">-0.5</button>\n                    <input type=\"number\" id=\"morningInput_${d.id}\" class=\"grade-input\" value=\"${d.morning_avg}\" step=\"0.1\" min=\"50\" max=\"100\">\n                    <button class=\"grade-btn add\" onclick=\"changeGrade(${d.id}, 'morning', 0.5)\">+0.5</button>\n                    <button class=\"grade-btn add\" onclick=\"changeGrade(${d.id}, 'morning', 1.0)\">+1</button>\n                </div>\n            </div>\n\n            <!-- Evening Avg Control -->\n            <div class=\"grade-control-row\">\n                <span class=\"grade-label\">مسائي:</span>\n                <div class=\"grade-adjusters\">\n                    <button class=\"grade-btn sub\" onclick=\"changeGrade(${d.id}, 'evening', -1.0)\">-1</button>\n                    <button class=\"grade-btn sub\" onclick=\"changeGrade(${d.id}, 'evening', -0.5)\">-0.5</button>\n                    <input type=\"number\" id=\"eveningInput_${d.id}\" class=\"grade-input\" value=\"${d.evening_avg}\" step=\"0.1\" min=\"50\" max=\"100\">\n                    <button class=\"grade-btn add\" onclick=\"changeGrade(${d.id}, 'evening', 0.5)\">+0.5</button>\n                    <button class=\"grade-btn add\" onclick=\"changeGrade(${d.id}, 'evening', 1.0)\">+1</button>\n                </div>\n            </div>\n\n            <div style=\"display: flex; gap: 8px; margin-top: 15px;\">\n                <button class=\"btn btn-accent\" style=\"flex: 1; padding: 6px; font-size: 0.85rem;\" onclick=\"saveGrade(${d.id})\">\n                    <i class=\"fas fa-check\"></i> حفظ التحديث\n                </button>\n                <button class=\"btn btn-outline\" style=\"padding: 6px 12px; font-size: 0.85rem;\" onclick=\"editDeptModal(${d.id})\" title=\"تعديل التفاصيل\">\n                    <i class=\"fas fa-edit\"></i>\n                </button>\n            </div>\n        `;\n        grid.appendChild(card);\n    });\n}\n\n// Render Departments Table\nfunction renderDepartmentsTable(depts) {\n    const tbody = document.getElementById('departmentsTableBody');\n    if (!tbody) return;\n    tbody.innerHTML = '';\n\n    depts.forEach((d, idx) => {\n        const tr = document.createElement('tr');\n        tr.innerHTML = `\n            <td>${idx + 1}</td>\n            <td>\n                <strong>${d.dept_name_ar}</strong>\n                <br><small style=\"color: var(--text-muted);\">${d.college_name_ar}</small>\n            </td>\n            <td><span class=\"dept-category-tag\">${getCatLabel(d.category)}</span></td>\n            <td><strong style=\"color: var(--accent-color);\">${d.morning_avg}%</strong></td>\n            <td><strong style=\"color: var(--secondary-color);\">${d.evening_avg}%</strong></td>\n            <td>${d.tuition_fee.toLocaleString()} دينار</td>\n            <td>\n                <div style=\"display: flex; gap: 5px;\">\n                    <button class=\"btn btn-outline\" style=\"padding: 4px 8px; font-size: 0.8rem;\" onclick=\"changeGrade(${d.id}, 'morning', 0.5)\">صباحي +0.5</button>\n                    <button class=\"btn btn-outline\" style=\"padding: 4px 8px; font-size: 0.8rem;\" onclick=\"changeGrade(${d.id}, 'morning', -0.5)\">صباحي -0.5</button>\n                </div>\n            </td>\n            <td>\n                <div style=\"display: flex; gap: 6px;\">\n                    <button class=\"btn btn-outline\" style=\"padding: 5px 10px;\" onclick=\"editDeptModal(${d.id})\" title=\"تعديل\"><i class=\"fas fa-edit\"></i></button>\n                    <button class=\"btn btn-outline\" style=\"padding: 5px 10px; color: #e74c3c; border-color: rgba(231,76,60,0.4);\" onclick=\"deleteDept(${d.id}, '${d.dept_name_ar}')\" title=\"حذف\"><i class=\"fas fa-trash-alt\"></i></button>\n                </div>\n            </td>\n        `;\n        tbody.appendChild(tr);\n    });\n}\n\n// Change Grade Helper (+0.5, -0.5, +1.0, -1.0)\nfunction changeGrade(deptId, type, delta) {\n    const inputId = type === 'morning' ? `morningInput_${deptId}` : `eveningInput_${deptId}`;\n    const input = document.getElementById(inputId);\n    if (!input) return;\n\n    let currentVal = parseFloat(input.value) || 50.0;\n    let newVal = Math.round((currentVal + delta) * 10) / 10;\n    if (newVal < 50) newVal = 50;\n    if (newVal > 100) newVal = 100;\n\n    input.value = newVal;\n    saveGrade(deptId);\n}\n\n// Save Grade Change to Database\nfunction saveGrade(deptId) {\n    const morningInput = document.getElementById(`morningInput_${deptId}`);\n    const eveningInput = document.getElementById(`eveningInput_${deptId}`);\n\n    const morning_avg = morningInput ? parseFloat(morningInput.value) : undefined;\n    const evening_avg = eveningInput ? parseFloat(eveningInput.value) : undefined;\n\n    const token = localStorage.getItem('adminToken');\n    fetch(`${API_BASE}/api/departments/${deptId}`, {\n        method: 'PUT',\n        headers: {\n            'Content-Type': 'application/json',\n            'Authorization': `Bearer ${token}`\n        },\n        body: JSON.stringify({ morning_avg, evening_avg })\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            fetchDepartments();\n        } else {\n            alert(data.message || 'خطأ أثناء التحديث');\n        }\n    })\n    .catch(err => console.error('Error saving grade:', err));\n}\n\n// Filter Quick Depts Search\nfunction filterQuickDepts() {\n    const query = document.getElementById('quickSearchInput').value.toLowerCase().trim();\n    const filtered = allDepartments.filter(d => \n        d.dept_name_ar.toLowerCase().includes(query) ||\n        d.college_name_ar.toLowerCase().includes(query)\n    );\n    renderQuickDepts(filtered);\n}\n\n// Category Label Mapping\nfunction getCatLabel(cat) {\n    if (cat === 'medical') return 'الطبية والصحية';\n    if (cat === 'engineering') return 'الهندسة والعلوم';\n    return 'العلوم الإنسانية';\n}\n\n// Add/Edit Department Modal\nfunction openAddDeptModal() {\n    document.getElementById('deptModalTitle').innerHTML = '<i class=\"fas fa-plus-circle\"></i> إضافة كلية / قسم جديد';\n    document.getElementById('deptFormId').value = '';\n    document.getElementById('deptForm').reset();\n    document.getElementById('deptModal').style.display = 'flex';\n}\n\nfunction editDeptModal(deptId) {\n    const dept = allDepartments.find(d => d.id === deptId);\n    if (!dept) return;\n\n    document.getElementById('deptModalTitle').innerHTML = '<i class=\"fas fa-edit\"></i> تعديل بيانت الكلية / القسم';\n    document.getElementById('deptFormId').value = dept.id;\n    document.getElementById('deptFormCollegeAr').value = dept.college_name_ar;\n    document.getElementById('deptFormCollegeEn').value = dept.college_name_en || '';\n    document.getElementById('deptFormNameAr').value = dept.dept_name_ar;\n    document.getElementById('deptFormNameEn').value = dept.dept_name_en || '';\n    document.getElementById('deptFormCategory').value = dept.category;\n    document.getElementById('deptFormTuition').value = dept.tuition_fee;\n    document.getElementById('deptFormMorningAvg').value = dept.morning_avg;\n    document.getElementById('deptFormEveningAvg').value = dept.evening_avg;\n    document.getElementById('deptFormIcon').value = dept.icon_class || 'fa-graduation-cap';\n    document.getElementById('deptFormImage').value = dept.image_url || 'assets/images/hero.webp';\n    document.getElementById('deptFormDescAr').value = dept.description_ar || '';\n\n    document.getElementById('deptModal').style.display = 'flex';\n}\n\nfunction closeDeptModal() {\n    document.getElementById('deptModal').style.display = 'none';\n}\n\nfunction saveDepartment(event) {\n    event.preventDefault();\n    const id = document.getElementById('deptFormId').value;\n    const isEdit = !!id;\n\n    const payload = {\n        college_name_ar: document.getElementById('deptFormCollegeAr').value,\n        college_name_en: document.getElementById('deptFormCollegeEn').value,\n        dept_name_ar: document.getElementById('deptFormNameAr').value,\n        dept_name_en: document.getElementById('deptFormNameEn').value,\n        category: document.getElementById('deptFormCategory').value,\n        tuition_fee: parseInt(document.getElementById('deptFormTuition').value),\n        morning_avg: parseFloat(document.getElementById('deptFormMorningAvg').value),\n        evening_avg: parseFloat(document.getElementById('deptFormEveningAvg').value),\n        icon_class: document.getElementById('deptFormIcon').value,\n        image_url: document.getElementById('deptFormImage').value,\n        description_ar: document.getElementById('deptFormDescAr').value\n    };\n\n    const token = localStorage.getItem('adminToken');\n    const url = isEdit ? `${API_BASE}/api/departments/${id}` : `${API_BASE}/api/departments`;\n    const method = isEdit ? 'PUT' : 'POST';\n\n    fetch(url, {\n        method,\n        headers: {\n            'Content-Type': 'application/json',\n            'Authorization': `Bearer ${token}`\n        },\n        body: JSON.stringify(payload)\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            closeDeptModal();\n            fetchDepartments();\n            fetchStats();\n            alert(data.message || 'تم حفظ البيانات بنجاح');\n        } else {\n            alert(data.message || 'حدث خطأ أثناء التحديث');\n        }\n    })\n    .catch(err => alert('خطأ بالاتصال بالسيرفر'));\n}\n\nfunction deleteDept(deptId, deptName) {\n    if (!confirm(`هل أنت تأكد من رغبتك في حذف (${deptName}) نهائياً من النظام؟`)) {\n        return;\n    }\n\n    const token = localStorage.getItem('adminToken');\n    fetch(`${API_BASE}/api/departments/${deptId}`, {\n        method: 'DELETE',\n        headers: { 'Authorization': `Bearer ${token}` }\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            fetchDepartments();\n            fetchStats();\n            alert('تم حذف القسم بنجاح');\n        } else {\n            alert(data.message || 'خطأ أثناء الحذف');\n        }\n    })\n    .catch(err => console.error('Error deleting dept:', err));\n}\n\n// --------------------------------------------------\n// STUDENTS MANAGEMENT\n// --------------------------------------------------\n\nfunction fetchStudents(status = 'all') {\n    const token = localStorage.getItem('adminToken');\n    const search = document.getElementById('studentSearchInput') ? document.getElementById('studentSearchInput').value : '';\n\n    let url = `${API_BASE}/api/registrations?status=${status}`;\n    if (search) url += `&search=${encodeURIComponent(search)}`;\n\n    fetch(url, {\n        headers: { 'Authorization': `Bearer ${token}` }\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            allStudents = data.data;\n            renderStudentsTable(allStudents);\n        }\n    })\n    .catch(err => console.error('Error fetching students:', err));\n}\n\nfunction renderStudentsTable(students) {\n    const tbody = document.getElementById('studentsTableBody');\n    if (!tbody) return;\n    tbody.innerHTML = '';\n\n    if (students.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"11\" style=\"text-align: center; color: var(--text-muted); padding: 25px;\">لا توجد استمارات مطابقة للبحث أو التصفية</td></tr>';\n        return;\n    }\n\n    students.forEach((s, idx) => {\n        const tr = document.createElement('tr');\n        tr.innerHTML = `\n            <td>${idx + 1}</td>\n            <td><strong>${s.student_name}</strong><br><small style=\"color: var(--text-muted);\">${s.email}</small></td>\n            <td><a href=\"https://wa.me/${s.phone.replace(/[^0-9]/g, '')}\" target=\"_blank\" style=\"color: var(--secondary-color); font-weight: 700;\">${s.phone} <i class=\"fab fa-whatsapp\"></i></a></td>\n            <td>${s.city}</td>\n            <td>${s.study_branch}</td>\n            <td><strong style=\"color: var(--accent-color); font-size: 1rem;\">${s.high_school_avg}%</strong></td>\n            <td>${s.dept_name}</td>\n            <td>${s.study_type}</td>\n            <td>${getStatusBadge(s.status)}</td>\n            <td>${new Date(s.created_at).toLocaleDateString('ar-IQ')}</td>\n            <td>\n                <div style=\"display: flex; gap: 4px;\">\n                    <button class=\"btn btn-outline\" style=\"padding: 4px 8px; color: #2ecc71; border-color: rgba(46,204,113,0.4);\" onclick=\"changeStudentStatus(${s.id}, 'accepted')\" title=\"قبول\"><i class=\"fas fa-check\"></i></button>\n                    <button class=\"btn btn-outline\" style=\"padding: 4px 8px; color: #e74c3c; border-color: rgba(231,76,60,0.4);\" onclick=\"changeStudentStatus(${s.id}, 'rejected')\" title=\"رفض\"><i class=\"fas fa-times\"></i></button>\n                    <button class=\"btn btn-outline\" style=\"padding: 4px 8px; color: #f1c40f; border-color: rgba(241,196,15,0.4);\" onclick=\"changeStudentStatus(${s.id}, 'pending')\" title=\"معلق\"><i class=\"fas fa-clock\"></i></button>\n                    <button class=\"btn btn-outline\" style=\"padding: 4px 8px;\" onclick=\"deleteStudent(${s.id})\" title=\"حذف\"><i class=\"fas fa-trash-alt\"></i></button>\n                </div>\n            </td>\n        `;\n        tbody.appendChild(tr);\n    });\n}\n\nfunction getStatusBadge(status) {\n    if (status === 'accepted') return '<span class=\"status-pill accepted\"><i class=\"fas fa-check-circle\"></i> مقبول</span>';\n    if (status === 'rejected') return '<span class=\"status-pill rejected\"><i class=\"fas fa-times-circle\"></i> مرفوض</span>';\n    return '<span class=\"status-pill pending\"><i class=\"fas fa-clock\"></i> قيد الانتظار</span>';\n}\n\nfunction changeStudentStatus(id, newStatus) {\n    const token = localStorage.getItem('adminToken');\n    fetch(`${API_BASE}/api/registrations/${id}/status`, {\n        method: 'PATCH',\n        headers: {\n            'Content-Type': 'application/json',\n            'Authorization': `Bearer ${token}`\n        },\n        body: JSON.stringify({ status: newStatus })\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            fetchStudents('all');\n            fetchStats();\n        } else {\n            alert(data.message || 'خطأ في تحديث الحالة');\n        }\n    })\n    .catch(err => console.error('Error changing student status:', err));\n}\n\nfunction deleteStudent(id) {\n    if (!confirm('هل أنت متاكد من حذف استمارة الطالب؟')) return;\n\n    const token = localStorage.getItem('adminToken');\n    fetch(`${API_BASE}/api/registrations/${id}`, {\n        method: 'DELETE',\n        headers: { 'Authorization': `Bearer ${token}` }\n    })\n    .then(res => res.json())\n    .then(data => {\n        if (data.success) {\n            fetchStudents('all');\n            fetchStats();\n        } else {\n            alert(data.message || 'خطأ أثناء الحذف');\n        }\n    })\n    .catch(err => console.error('Error deleting student:', err));\n}\n\nfunction filterStudents(status, btn) {\n    document.querySelectorAll('.filter-tab').forEach(b => b.classList.remove('active'));\n    btn.classList.add('active');\n    fetchStudents(status);\n}\n\nfunction searchStudents() {\n    fetchStudents('all');\n}\n\n// Switch Tabs\nfunction switchTab(tabName, el) {\n    document.querySelectorAll('.menu-item').forEach(m => m.classList.remove('active'));\n    if (el) el.classList.add('active');\n\n    document.querySelectorAll('.tab-content').forEach(tc => tc.style.display = 'none');\n\n    const titles = {\n        'overview': 'نظرة عامة والمعدلات الحالية',\n        'departments': 'إدارة الكليات والأقسام والمعدلات والأقساط',\n        'students': 'استمارات الطلاب المسجلين وطلبات القبول'\n    };\n\n    if (tabName === 'overview') {\n        document.getElementById('tabOverview').style.display = 'block';\n    } else if (tabName === 'departments') {\n        document.getElementById('tabDepartments').style.display = 'block';\n    } else if (tabName === 'students') {\n        document.getElementById('tabStudents').style.display = 'block';\n    }\n\n    document.getElementById('pageTitle').textContent = titles[tabName] || 'لوحة التحكم';\n}\n"
};